import {ORGANIC,AROMATIC} from './smiles_parser.ts';
import {needsPi,organicHydrogens} from './molecule.ts';
import type {Molecule} from './molecule.ts';
import type {Atom,Bond,Neighbor} from './types.ts';

type RankValue = number | RankValue[];

export function compareValues(first:RankValue,second:RankValue):number {
  if (!Array.isArray(first)) return (first as number) - (second as number);
  for (let i = 0; i < Math.min(first.length, (second as RankValue[]).length); i++) {
    const difference = compareValues(first[i], (second as RankValue[])[i]);
    if (difference !== 0) return difference;
  }
  return first.length - (second as RankValue[]).length;
}

export function denseRanks(values:RankValue[]):number[] {
  const indices = values.map((value, i) => i).sort((a, b) => compareValues(values[a], values[b]));
  const ranks:number[] = Array(values.length);
  let rank = 0, previous:RankValue|null = null;
  for (const index of indices) {
    if (previous === null || compareValues(values[index], previous) !== 0) rank++;
    ranks[index] = rank; previous = values[index];
  }
  return ranks;
}

export function refine(molecule:Molecule,initial:number[]):number[] {
  let ranks = initial;
  while (true) {
    const values = molecule.atoms.map((atom, i) => [ranks[i], atom.neighbors
      .map(neighbor => [ranks[neighbor.atom], neighbor.bond.type!]).sort(compareValues)]);
    const next = denseRanks(values), unchanged = new Set(next).size === new Set(ranks).size;
    ranks = next;
    if (unchanged) return ranks;
  }
}

export function canonicalRanks(molecule:Molecule):{ranks:number[];classes:number} {
  const invariants = molecule.atoms.map(atom => [atom.neighbors.length, atom.element.number, atom.mass,
    atom.charge, atom.hydrogens, atom.aromatic ? 1 : 0]);
  let ranks = refine(molecule, denseRanks(invariants));
  const classes = new Set(ranks).size;
  while (new Set(ranks).size < molecule.atoms.length) {
    const counts = new Map<number,number>();
    for (const rank of ranks) counts.set(rank, (counts.get(rank) || 0) + 1);
    const tied = Math.min(...Array.from(counts.keys()).filter(rank => counts.get(rank)! > 1)), atom = ranks.indexOf(tied);
    ranks = refine(molecule, denseRanks(ranks.map((rank, i) => 2 * rank - (i === atom ? 1 : 0))));
  }
  return { ranks, classes };
}

export function atomText(atom:Atom):string {
  const symbol = atom.aromatic ? atom.element.symbol.toLowerCase() : atom.element.symbol;
  const organic = ORGANIC.has(atom.element.symbol) && (!atom.aromatic || AROMATIC.has(symbol));
  if (organic && atom.mass === 0 && atom.charge === 0 && (!atom.aromatic || needsPi(atom) === needsPi(atom, 0))
      && organicHydrogens(atom) === atom.hydrogens) return symbol;
  const mass = atom.mass === 0 ? '' : String(atom.mass);
  const hydrogen = atom.hydrogens === 0 ? '' : atom.hydrogens === 1 ? 'H' : 'H' + atom.hydrogens;
  const charge = atom.charge === 0 ? '' : (atom.charge > 0 ? '+' : '-') + (Math.abs(atom.charge) === 1 ? '' : Math.abs(atom.charge));
  return '[' + mass + symbol + hydrogen + charge + ']';
}

export function bondText(molecule:Molecule,bond:Bond):string {
  const inRingAromatic = molecule.atoms[bond.a].aromatic && molecule.atoms[bond.b].aromatic && bond.ring;
  if (bond.type === 1) return inRingAromatic ? '-' : '';
  if (bond.type === 2) return '=';
  if (bond.type === 3) return '#';
  return inRingAromatic ? '' : ':';
}

export function canonicalize(molecule:Molecule):{smiles:string;ranks:number[];classes:number} {
  const { ranks, classes } = canonicalRanks(molecule), start = ranks.indexOf(1), visited = new Set<number>();
  const children:Neighbor[][] = molecule.atoms.map(() => []), order:number[] = Array(molecule.atoms.length), closures = new Set<number>();
  const visit = (atom:number, incoming:Bond|null):void => {
    visited.add(atom); order[atom] = visited.size;
    const neighbors = molecule.atoms[atom].neighbors.slice().sort((a, b) => ranks[a.atom] - ranks[b.atom]);
    for (const neighbor of neighbors) {
      if (neighbor.bond === incoming || closures.has(neighbor.bond.index)) continue;
      if (!visited.has(neighbor.atom)) { children[atom].push(neighbor); visit(neighbor.atom, neighbor.bond); }
      else closures.add(neighbor.bond.index);
    }
  };
  visit(start, null);
  const assignments = new Map<number,number>(), occupied = new Set<number>();
  const ringNumber = (number:number):string => number < 10 ? String(number) : '%' + String(number).padStart(2, '0');
  const write = (atom:number):string => {
    let text = atomText(molecule.atoms[atom]);
    const ends = molecule.atoms[atom].neighbors.filter(neighbor => closures.has(neighbor.bond.index)).sort((a, b) => order[a.atom] - order[b.atom]);
    for (const neighbor of ends) {
      const index = neighbor.bond.index;
      if (assignments.has(index)) {
        const number = assignments.get(index)!; text += ringNumber(number); assignments.delete(index); occupied.delete(number);
      } else {
        let number = 1;
        while (occupied.has(number)) number++;
        assignments.set(index, number); occupied.add(number); text += bondText(molecule, neighbor.bond) + ringNumber(number);
      }
    }
    children[atom].forEach((child, i) => {
      const branch = bondText(molecule, child.bond) + write(child.atom);
      text += i + 1 === children[atom].length ? branch : '(' + branch + ')';
    });
    return text;
  };
  return { smiles: write(start), ranks, classes };
}

import {mkdirSync,writeFileSync} from 'node:fs';
import {MoleculeError,dataLines,readElements,Molecule,multiplicityTotal,needsPi,organicHydrogens} from './molecule.ts';
import {parseSmiles} from './smiles_parser.ts';
import {findRings,kekulize} from './rings_aromatic.ts';
import {canonicalize} from './canonical.ts';
import {readPatternAtom,moleculePattern,embeddings,fingerprint,similarity} from './search.ts';
import type {
  Element, Atom, MolecularProperties, RingSystem, MoleculeCollection,
  Query, QueryCollection, Ratio, Similarity, Embeddings
} from './types.ts';

const TYPES = ['MATCH', 'CONTAINS', 'MATRIX', 'NEAREST', 'WITHIN', 'COMPARE', 'CLUSTER'];
const validName = (text:string|undefined):boolean => typeof text === 'string' && /^[A-Za-z0-9_-]{1,32}$/.test(text);
const asciiCompare = (a:string,b:string):number => a < b ? -1 : a > b ? 1 : 0;
const validNumber = (text:string,low:number,high:number):boolean => /^(0|[1-9][0-9]*)$/.test(text) && Number(text) >= low && Number(text) <= high;
const fractionCompare = (a:Ratio,b:Ratio):number => a.p * b.q - b.p * a.q;
const names = (molecules:Molecule[]):string => molecules.map(molecule => molecule.name).join(',');

function fractionText(value:Ratio):string {
  if (value.p === 0) return '0/1';
  let a = value.p, b = value.q;
  while (b !== 0) [a, b] = [b, a % b];
  return value.p / a + '/' + value.q / a;
}

function threshold(text:string):Ratio|null {
  const values = text.split('/');
  if (values.length !== 2 || !validNumber(values[0], 0, 99) || !validNumber(values[1], 1, 99) || Number(values[0]) > Number(values[1])) return null;
  return { p: Number(values[0]), q: Number(values[1]) };
}

function analyze(molecule:Molecule):void {
  findRings(molecule);
  for (const bond of molecule.bonds) {
    bond.type = bond.rawType === null ? molecule.atoms[bond.a].aromatic && molecule.atoms[bond.b].aromatic && bond.ring ? 4 : 1 : bond.rawType;
  }
  const needed = new Set<number>(molecule.atoms.filter(atom => needsPi(atom)).map(atom => atom.index));
  kekulize(molecule, needed);
  for (const atom of molecule.atoms) {
    if (atom.bracket) {
      if (multiplicityTotal(atom) + atom.hydrogens > atom.element.maximum + Math.abs(atom.charge)) throw new MoleculeError('bad valence', atom.column);
    } else {
      const hydrogens = organicHydrogens(atom);
      if (hydrogens === null) throw new MoleculeError('bad valence', atom.column);
      atom.hydrogens = hydrogens;
    }
  }
}

function molecularProperties(molecule:Molecule,elements:Map<string,Element>):MolecularProperties {
  const counts = new Map<string,number>();
  let weight = 0, hydrogens = 0, heavy = 0, charge = 0, donors = 0, acceptors = 0, rotatable = 0;
  const heavyDegrees = molecule.atoms.map(atom => atom.neighbors.filter(neighbor => molecule.atoms[neighbor.atom].element.symbol !== 'H').length);
  const triples = molecule.atoms.map(atom => atom.neighbors.some(neighbor => neighbor.bond.multiplicity === 3));
  for (const atom of molecule.atoms) {
    const symbol = atom.element.symbol;
    counts.set(symbol, (counts.get(symbol) || 0) + 1); hydrogens += atom.hydrogens;
    weight += atom.mass === 0 ? atom.element.mass : atom.mass * 1000; charge += atom.charge;
    if (symbol !== 'H') heavy++;
    if (symbol === 'N' || symbol === 'O') {
      acceptors++;
      const attached = atom.hydrogens + atom.neighbors.filter(neighbor => molecule.atoms[neighbor.atom].element.symbol === 'H').length;
      if (attached > 0) donors++;
    }
  }
  if (hydrogens > 0) counts.set('H', (counts.get('H') || 0) + hydrogens);
  weight += hydrogens * elements.get('H')!.mass;
  let symbols = Array.from(counts.keys()).sort(asciiCompare);
  if (counts.has('C')) symbols = ['C', ...(counts.has('H') ? ['H'] : []), ...symbols.filter(symbol => symbol !== 'C' && symbol !== 'H')];
  const formula = symbols.map(symbol => symbol + (counts.get(symbol) === 1 ? '' : counts.get(symbol))).join('');
  for (const bond of molecule.bonds) {
    if (bond.multiplicity === 1 && !bond.ring && heavyDegrees[bond.a] >= 2 && heavyDegrees[bond.b] >= 2 && !triples[bond.a] && !triples[bond.b]) rotatable++;
  }
  const violations = Number(weight > 500000) + Number(donors > 5) + Number(acceptors > 10);
  return { formula, weight, weightText: Math.floor(weight / 1000) + '.' + String(weight % 1000).padStart(3, '0'), heavy,
    rings: molecule.rings.length, rotatable, donors, acceptors, lipinski: violations <= 1 ? 'pass' : 'fail', charge };
}

function scaffold(molecule:Molecule):string|null {
  if (molecule.rings.length === 0) return null;
  const remaining = new Set<number>(molecule.atoms.map(atom => atom.index));
  while (true) {
    const removable = molecule.atoms.find(atom => remaining.has(atom.index) && !atom.ring &&
      atom.neighbors.filter(neighbor => remaining.has(neighbor.atom)).length === 1);
    if (!removable) break;
    remaining.delete(removable.index);
  }
  const kept = new Set<number>(remaining);
  for (const index of remaining) for (const neighbor of molecule.atoms[index].neighbors) {
    if (!remaining.has(neighbor.atom) && neighbor.bond.type === 2) kept.add(neighbor.atom);
  }
  const result = new Molecule(), renumber = new Map<number,number>();
  for (const atom of molecule.atoms) if (kept.has(atom.index)) {
    const extra = atom.neighbors.filter(neighbor => !kept.has(neighbor.atom)).reduce((sum, neighbor) => sum + neighbor.bond.multiplicity, 0);
    const index = result.addAtom({ ...atom, hydrogens: atom.hydrogens + extra });
    renumber.set(atom.index, index); result.atoms[index].ring = atom.ring;
  }
  for (const original of molecule.bonds) if (kept.has(original.a) && kept.has(original.b)) {
    const bond = result.addBond(renumber.get(original.a)!, renumber.get(original.b)!, original.rawType);
    bond.type = original.type; bond.multiplicity = original.multiplicity; bond.ring = original.ring;
  }
  result.finalize();
  return canonicalize(result).smiles;
}

function ringSystems(molecule:Molecule):RingSystem[] {
  const rings = molecule.rings, sets = rings.map(ring => new Set<number>(ring)), relations = new Map<string,string>();
  const neighbors:number[][] = rings.map(() => []);
  for (let i = 0; i < rings.length; i++) for (let j = i + 1; j < rings.length; j++) {
    const common = rings[i].filter(atom => sets[j].has(atom));
    if (common.length === 0) continue;
    const relation = common.length === 1 ? 'spiro' : common.length === 2 && molecule.bond(common[0], common[1]) ? 'fused' : 'bridged';
    neighbors[i].push(j); neighbors[j].push(i); relations.set(i + ',' + j, relation);
  }
  const visited = new Set<number>(), systems:RingSystem[] = [];
  for (let i = 0; i < rings.length; i++) {
    if (visited.has(i)) continue;
    const component = [i]; visited.add(i);
    for (let front = 0; front < component.length; front++) for (const j of neighbors[component[front]]) if (!visited.has(j)) {
      visited.add(j); component.push(j);
    }
    component.sort((a, b) => a - b);
    let kind = component.length === 1 ? 'isolated' : 'spiro';
    for (let a = 0; a < component.length; a++) for (let b = a + 1; b < component.length; b++) {
      const relation = relations.get(component[a] + ',' + component[b]);
      if (relation === 'bridged') kind = 'bridged';
      else if (relation === 'fused' && kind !== 'bridged') kind = 'fused';
    }
    const atoms = new Set<number>(component.flatMap(index => rings[index]));
    systems.push({ rings: component.map(index => index + 1), kind, atoms: atoms.size });
  }
  return systems;
}

function readMolecules(elements:Map<string,Element>,causes:Map<string,number>):MoleculeCollection {
  const records = dataLines('input/molecules.smi'), used = new Set<string>();
  const molecules:Molecule[] = [], errors:string[] = [], byName = new Map<string,Molecule>();
  const reject = (line:string,cause:string):void => { errors.push(line); causes.set(cause, (causes.get(cause) || 0) + 1); };
  for (const record of records) {
    const fields = record.text.split(' ');
    if (fields.length !== 2 || fields[0] === '' || !validName(fields[1])) { reject(`line ${record.line}: bad line`, 'bad line'); continue; }
    const [text, name] = fields;
    if (used.has(name)) { reject(`line ${record.line} ${name}: duplicate name`, 'duplicate name'); continue; }
    used.add(name);
    try {
      const molecule = parseSmiles(text, elements); analyze(molecule);
      molecule.name = name; molecule.index = molecules.length; molecules.push(molecule); byName.set(name, molecule);
    } catch (error) {
      if (!(error instanceof MoleculeError)) throw error;
      reject(`line ${record.line} ${name}: ${error.reason} at column ${error.column}`, error.reason);
    }
  }
  for (const molecule of molecules) {
    molecule.properties = molecularProperties(molecule, elements);
    const canonical = canonicalize(molecule);
    molecule.canonical = canonical.smiles; molecule.classes = canonical.classes; molecule.scaffold = scaffold(molecule);
    molecule.systems = ringSystems(molecule); molecule.fingerprint = fingerprint(molecule);
  }
  return { records, molecules, byName, errors };
}

function readQueries(elements:Map<string,Element>,molecules:MoleculeCollection,causes:Map<string,number>):QueryCollection {
  const records = dataLines('input/queries.txt'), used = new Set<string>(), queries:Query[] = [], errors:string[] = [];
  const reject = (line:string,cause:string):void => { errors.push(line); causes.set(cause, (causes.get(cause) || 0) + 1); };
  for (const record of records) {
    const [type, id, ...args] = record.text.split(' ');
    if (!TYPES.includes(type)) { reject(`line ${record.line}: unknown query`, 'unknown query'); continue; }
    if (!validName(id)) { reject(`line ${record.line} ${type}: bad id`, 'bad id'); continue; }
    const prefix = `line ${record.line} ${type} ${id}: `;
    if (used.has(id)) { reject(prefix + 'duplicate id', 'duplicate id'); continue; }
    used.add(id);
    const count = type === 'MATCH' || type === 'CLUSTER' ? args.length === 1 : type === 'MATRIX' ? args.length >= 2 && args.length <= 12 : args.length === 2;
    if (!count) { reject(prefix + 'bad arguments', 'bad arguments'); continue; }
    const query:Query = {type,id,args};
    let reason:string|null = null, cause:string|null = null;
    if (type === 'MATCH') {
      try { query.pattern = parseSmiles(args[0], elements, readPatternAtom); }
      catch (error) {
        if (!(error instanceof MoleculeError)) throw error;
        reason = `bad pattern ${error.reason} at column ${error.column}`; cause = 'bad pattern';
      }
    } else if (type === 'CLUSTER') {
      query.threshold = threshold(args[0]);
      if (query.threshold === null) reason = cause = 'bad threshold';
    } else {
      const requested = type === 'NEAREST' || type === 'WITHIN' ? args.slice(0, 1) : args;
      const unknown = requested.find(name => !molecules.byName.has(name));
      if (unknown !== undefined) { reason = 'unknown molecule ' + unknown; cause = 'unknown molecule'; }
      else if (type === 'NEAREST') {
        if (!validNumber(args[1], 1, 99)) reason = cause = 'bad count';
        else query.count = Number(args[1]);
      } else if (type === 'WITHIN') {
        query.threshold = threshold(args[1]);
        if (query.threshold === null) reason = cause = 'bad threshold';
      } else if (new Set(args).size !== args.length) reason = cause = 'repeated molecule';
      if (reason === null) query.molecules = requested.map(name => molecules.byName.get(name)!);
    }
    if (reason !== null) reject(prefix + reason, cause!);
    else queries.push(query);
  }
  return { records, queries, errors };
}

function groupBy(molecules:Molecule[],key:(molecule:Molecule)=>string):Map<string,Molecule[]> {
  const groups = new Map<string,Molecule[]>();
  for (const molecule of molecules) {
    const value = key(molecule);
    if (!groups.has(value)) groups.set(value, []);
    groups.get(value)!.push(molecule);
  }
  return groups;
}

function canonicalReport(molecules:Molecule[]):string[][] {
  const byCanonical = groupBy(molecules, molecule => molecule.canonical), byFormula = groupBy(molecules, molecule => molecule.properties.formula);
  const canonical = [`CANONICAL molecules=${molecules.length} unique=${byCanonical.size}`];
  for (const molecule of molecules) {
    const charge = molecule.properties.charge;
    canonical.push(`${molecule.name} ${molecule.canonical} classes=${molecule.classes} charge=${charge > 0 ? '+' : ''}${charge}`);
  }
  const duplicateGroups = Array.from(byCanonical).filter(([, members]) => members.length >= 2);
  const duplicates = [`DUPLICATES groups=${duplicateGroups.length} molecules=${duplicateGroups.reduce((sum, [, members]) => sum + members.length, 0)}`];
  duplicateGroups.forEach(([smiles, members], i) => duplicates.push(`group ${i + 1} ${smiles} members=${names(members)}`));
  const isomerGroups = Array.from(byFormula).map(([formula, members]) => ({ formula, members, forms: new Set(members.map(molecule => molecule.canonical)).size }))
    .filter(group => group.forms >= 2);
  const isomers = [`ISOMERS groups=${isomerGroups.length}`];
  isomerGroups.forEach((group, i) => isomers.push(`isomer ${i + 1} ${group.formula} forms=${group.forms} members=${names(group.members)}`));
  const cyclic = molecules.filter(molecule => molecule.scaffold !== null), byScaffold = groupBy(cyclic, molecule => molecule.scaffold!);
  const scaffoldGroups = Array.from(byScaffold).sort((a, b) => b[1].length - a[1].length || asciiCompare(a[0], b[0]));
  const scaffolds = [`SCAFFOLDS distinct=${byScaffold.size} acyclic=${molecules.length - cyclic.length}`];
  scaffoldGroups.forEach(([smiles, members], i) => scaffolds.push(`scaffold ${i + 1} ${smiles} count=${members.length} members=${names(members)}`));
  return [canonical, duplicates, isomers, scaffolds];
}

function ringsReport(molecules:Molecule[]):string[][] {
  const paragraphs:string[][] = [], sizes = new Map<number,number>(), kinds:Record<string,number> = { isolated: 0, fused: 0, spiro: 0, bridged: 0 };
  let ringCount = 0, aromaticCount = 0;
  for (const molecule of molecules) {
    if (molecule.rings.length === 0) continue;
    const descriptions = molecule.rings.map(ring => ({ ring, aromatic: ring.every(index => molecule.atoms[index].aromatic),
      hetero: ring.filter(index => molecule.atoms[index].element.symbol !== 'C').length }));
    const aromatic = descriptions.filter(ring => ring.aromatic).length;
    const ringAtoms = molecule.atoms.filter(atom => atom.ring).length, ringBonds = molecule.bonds.filter(bond => bond.ring).length;
    const lines = [`MOLECULE ${molecule.name} atoms=${molecule.atoms.length} bonds=${molecule.bonds.length} rings=${molecule.rings.length} aromatic=${aromatic} systems=${molecule.systems.length} ring_atoms=${ringAtoms} ring_bonds=${ringBonds}`];
    descriptions.forEach((description, i) => {
      const { ring, aromatic, hetero } = description;
      lines.push(`ring ${i + 1} size=${ring.length} aromatic=${aromatic ? 'yes' : 'no'} hetero=${hetero} atoms=${ring.map(index => index + 1).join('-')}`);
      sizes.set(ring.length, (sizes.get(ring.length) || 0) + 1);
    });
    molecule.systems.forEach((system, i) => {
      lines.push(`system ${i + 1} kind=${system.kind} rings=${system.rings.join(',')} atoms=${system.atoms}`); kinds[system.kind]++;
    });
    const kekule = molecule.bonds.filter(bond => bond.type === 4 && bond.multiplicity === 2).map(bond => `${bond.a + 1}=${bond.b + 1}`);
    lines.push('kekule ' + (kekule.length ? kekule.join(' ') : '-'));
    paragraphs.push(lines); ringCount += molecule.rings.length; aromaticCount += aromatic;
  }
  const sizeText = Array.from(sizes.keys()).sort((a, b) => a - b).map(size => size + '=' + sizes.get(size));
  paragraphs.push([`SUMMARY molecules=${molecules.length} cyclic=${paragraphs.length} rings=${ringCount} aromatic=${aromaticCount}`,
    'sizes ' + (sizeText.length ? sizeText.join(' ') : '-'),
    `systems isolated=${kinds.isolated} fused=${kinds.fused} spiro=${kinds.spiro} bridged=${kinds.bridged}`]);
  return paragraphs;
}

function substructureReport(molecules:Molecule[],queries:Query[]):string[][] {
  const paragraphs:string[][] = [];
  let patterns = 0, hits = 0, contains = 0, found = 0;
  for (const query of queries) {
    if (query.type === 'MATCH') {
      patterns++;
      const matches:({molecule:Molecule}&Embeddings)[] = [], lines:string[] = [];
      let total = 0, top:({molecule:Molecule}&Embeddings)|null = null;
      for (const molecule of molecules) {
        const result = embeddings(query.pattern!, molecule);
        if (result.count === 0) continue;
        const match = { molecule, ...result }; matches.push(match); total += result.count;
        if (top === null || result.count > top.count) top = match;
      }
      hits += matches.length;
      lines.push(`MATCH ${query.id} ${query.args[0]} atoms=${query.pattern!.atoms.length} bonds=${query.pattern!.bonds.length} hits=${matches.length} embeddings=${total}`);
      for (const match of matches) lines.push(`${match.molecule.name} count=${match.count} unique=${match.unique} map=${match.first!.join(',')}`);
      if (top !== null) lines.push(`top ${top.molecule.name} count=${top.count}`);
      paragraphs.push(lines);
    } else if (query.type === 'CONTAINS') {
      contains++;
      const [first, second] = query.molecules!, result = embeddings(moleculePattern(first), second);
      const prefix = `CONTAINS ${query.id} ${first.name} ${second.name} result=`;
      if (result.count > 0) {
        found++; paragraphs.push([prefix + `yes count=${result.count} unique=${result.unique} map=${result.first!.join(',')}`]);
      } else paragraphs.push([prefix + 'no']);
    }
  }
  paragraphs.push([`SUMMARY patterns=${patterns} hits=${hits} contains=${contains} found=${found}`]);
  return paragraphs;
}

function similarityReport(molecules:Molecule[],queries:Query[]):string[][] {
  const fingerprints = [`FINGERPRINTS molecules=${molecules.length} size=1024 depth=5`];
  for (const molecule of molecules) fingerprints.push(`${molecule.name} bits=${molecule.fingerprint.bits.size} paths=${molecule.fingerprint.paths}`);
  const paragraphs:string[][] = [fingerprints], cache = new Map<number,Similarity>();
  const coefficient = (first:Molecule,second:Molecule):Similarity => {
    const key = Math.min(first.index, second.index) * molecules.length + Math.max(first.index, second.index);
    if (!cache.has(key)) cache.set(key, similarity(first.fingerprint, second.fingerprint));
    return cache.get(key)!;
  };
  for (const query of queries) {
    const { type, id } = query;
    if (type === 'MATCH' || type === 'CONTAINS') continue;
    const lines = [];
    if (type === 'MATRIX') {
      const requested = query.molecules!;
      lines.push(`MATRIX ${id} size=${requested.length}`);
      for (const molecule of requested) lines.push('row ' + molecule.name + ' ' + requested.map(other => fractionText(coefficient(molecule, other))).join(' '));
      let best: {first:Molecule;second:Molecule;value:Similarity}|null = null;
      for (let i = 0; i < requested.length; i++) for (let j = i + 1; j < requested.length; j++) {
        const value = coefficient(requested[i], requested[j]);
        if (best === null || fractionCompare(value, best.value) > 0) best = { first: requested[i], second: requested[j], value };
      }
      lines.push(`best ${best.first.name} ${best.second.name} ${fractionText(best.value)}`);
    } else if (type === 'NEAREST' || type === 'WITHIN') {
      const source = query.molecules![0];
      let results = molecules.filter(molecule => molecule !== source).map(molecule => ({ molecule, value: coefficient(source, molecule) }));
      results.sort((a, b) => -fractionCompare(a.value, b.value) || a.molecule.index - b.molecule.index);
      results = type === 'NEAREST' ? results.slice(0, query.count!) : results.filter(result => fractionCompare(result.value, query.threshold!) >= 0);
      lines.push(`${type} ${id} ${source.name}` + (type === 'WITHIN' ? ' threshold=' + fractionText(query.threshold!) : '') + ' count=' + results.length);
      results.forEach((result, i) => lines.push(`${i + 1} ${result.molecule.name} ${fractionText(result.value)} common=${result.value.common}`));
    } else if (type === 'COMPARE') {
      const [first, second] = query.molecules!, value = coefficient(first, second);
      lines.push(`COMPARE ${id} ${first.name} ${second.name} bits=${first.fingerprint.bits.size},${second.fingerprint.bits.size} common=${value.common} union=${value.union} tanimoto=${fractionText(value)} identical=${first.canonical === second.canonical ? 'yes' : 'no'}`);
    } else {
      const neighbors = molecules.map(molecule => molecules.filter(other => other !== molecule && fractionCompare(coefficient(molecule, other), query.threshold!) >= 0));
      const order = molecules.slice().sort((a, b) => neighbors[b.index].length - neighbors[a.index].length || a.index - b.index);
      const assigned = new Set<number>(), clusters:{center:Molecule;members:Molecule[]}[] = [];
      for (const center of order) if (!assigned.has(center.index)) {
        const members = [center, ...neighbors[center.index].filter(molecule => !assigned.has(molecule.index))];
        for (const molecule of members) assigned.add(molecule.index);
        clusters.push({ center, members });
      }
      const singletons = clusters.filter(cluster => cluster.members.length === 1).length;
      lines.push(`CLUSTER ${id} threshold=${fractionText(query.threshold!)} clusters=${clusters.length} singletons=${singletons}`);
      let number = 0;
      for (const cluster of clusters) if (cluster.members.length >= 2) {
        lines.push(`cluster ${++number} centroid=${cluster.center.name} size=${cluster.members.length} members=${names(cluster.members)}`);
      }
    }
    paragraphs.push(lines);
  }
  return paragraphs;
}

function errorsReport(molecules:MoleculeCollection,queries:QueryCollection,causes:Map<string,number>):string[][] {
  const first = [`MOLECULES lines=${molecules.records.length} valid=${molecules.molecules.length} errors=${molecules.errors.length}`, ...molecules.errors];
  const second = [`QUERIES lines=${queries.records.length} valid=${queries.queries.length} errors=${queries.errors.length}`, ...queries.errors];
  const ordered = Array.from(causes).sort((a, b) => b[1] - a[1] || asciiCompare(a[0], b[0]));
  const third = [`CAUSES kinds=${causes.size}`, ...ordered.map(([cause, count]) => cause + '=' + count)];
  return [first, second, third];
}

function main():void {
  const elements = readElements('input/elements.txt'), causes = new Map<string,number>();
  const moleculeData = readMolecules(elements, causes), queryData = readQueries(elements, moleculeData, causes);
  const molecules = moleculeData.molecules, queries = queryData.queries;
  const properties = ['name,formula,weight,heavy_atoms,rings,rotatable,donors,acceptors,lipinski'];
  for (const molecule of molecules) {
    const value = molecule.properties;
    properties.push([molecule.name, value.formula, value.weightText, value.heavy, value.rings, value.rotatable, value.donors, value.acceptors, value.lipinski].join(','));
  }
  const reports:[string,string[][]][] = [
    ['canonical.txt', canonicalReport(molecules)], ['rings.txt', ringsReport(molecules)],
    ['substructure.txt', substructureReport(molecules, queries)], ['similarity.txt', similarityReport(molecules, queries)],
    ['errors.txt', errorsReport(moleculeData, queryData, causes)],
  ];
  mkdirSync('output', { recursive: true });
  writeFileSync('output/properties.csv', properties.join('\n') + '\n', 'ascii');
  for (const [name, paragraphs] of reports) writeFileSync('output/' + name, paragraphs.map(lines => lines.join('\n')).join('\n\n') + '\n', 'ascii');
}

main();

import {readFileSync} from 'node:fs';
import type {Element,Atom,AtomSpec,Bond,MolecularProperties,RingSystem,Fingerprint,MoleculeRecord} from './types.ts';

export class MoleculeError extends Error {
  reason:string;
  column:number;
  constructor(reason:string,column:number) { super(reason); this.reason = reason; this.column = column; }
}

export function dataLines(path:string): MoleculeRecord[] {
  return readFileSync(path, 'ascii').split('\n').slice(0, -1).map((text, index) => ({ text, line: index + 1 }))
    .filter(record => record.text !== '' && !record.text.startsWith('#'));
}

export function readElements(path:string): Map<string,Element> {
  const elements = new Map<string,Element>();
  for (const { text } of dataLines(path)) {
    const [symbol, number, mass, valences] = text.split(' '), values = valences.split(',').map(Number);
    elements.set(symbol, { symbol, number: Number(number), mass: Number(mass), valences: values, base: values[0], maximum: values[values.length - 1] });
  }
  return elements;
}

export class Molecule {
  atoms:Atom[];
  bonds:Bond[];
  rings:number[][];
  name!:string;
  index!:number;
  properties!:MolecularProperties;
  canonical!:string;
  classes!:number;
  scaffold!:string|null;
  systems!:RingSystem[];
  fingerprint!:Fingerprint;
  constructor() {this.atoms=[];this.bonds=[];this.rings=[];}
  addAtom(atom:AtomSpec):number {
    const index = this.atoms.length;
    this.atoms.push({ ...atom, index, neighbors: [], ring: false } as Atom); return index;
  }
  addBond(first:number,second:number,rawType:number|null):Bond {
    const bond:Bond = { a: Math.min(first, second), b: Math.max(first, second), rawType, type: null, multiplicity: 0, ring: false, index:-1 };
    this.bonds.push(bond);
    this.atoms[first].neighbors.push({ atom: second, bond }); this.atoms[second].neighbors.push({ atom: first, bond });
    return bond;
  }
  bond(first:number,second:number):Bond|undefined { return this.atoms[first].neighbors.find(neighbor => neighbor.atom === second)?.bond; }
  finalize():Molecule {
    this.bonds.sort((a, b) => a.a - b.a || a.b - b.b);
    this.bonds.forEach((bond, index) => { bond.index = index; });
    for (const atom of this.atoms) atom.neighbors.sort((a, b) => a.atom - b.atom);
    return this;
  }
}

export const baseTotal = (atom:Atom):number => atom.neighbors.reduce((sum, neighbor) => sum + (neighbor.bond.type === 4 ? 1 : neighbor.bond.type!), 0);
export const multiplicityTotal = (atom:Atom):number => atom.neighbors.reduce((sum, neighbor) => sum + neighbor.bond.multiplicity, 0);
export const needsPi = (atom:Atom, hydrogens:number = atom.hydrogens):boolean => atom.aromatic && atom.element.base + atom.charge >= baseTotal(atom) + hydrogens + 1;
export function organicHydrogens(atom:Atom):number|null {
  const bonds = multiplicityTotal(atom), valence = atom.element.valences.find(value => value >= bonds);
  return valence === undefined ? null : valence - bonds;
}

import {MoleculeError} from './molecule.ts';
import type {Molecule} from './molecule.ts';
import type {RingCandidate} from './types.ts';

export function compareSequence(a:number[],b:number[]):number {
  for (let i = 0; i < Math.min(a.length, b.length); i++) if (a[i] !== b[i]) return a[i] - b[i];
  return a.length - b.length;
}

export function normalizeRing(sequence:number[]):number[] {
  const minimum = Math.min(...sequence), index = sequence.indexOf(minimum), ring = sequence.slice(index).concat(sequence.slice(0, index));
  return ring[1] < ring[ring.length - 1] ? ring : [ring[0], ...ring.slice(1).reverse()];
}

export function findRings(molecule:Molecule):number[][] {
  const candidates:RingCandidate[] = [], seen = new Set<string>(), size = molecule.atoms.length;
  for (let root = 0; root < size; root++) {
    const parent = Array(size).fill(-1), visited = Array(size).fill(false), queue = [root];
    visited[root] = true;
    for (let front = 0; front < queue.length; front++) {
      const atom = queue[front];
      for (const neighbor of molecule.atoms[atom].neighbors) if (!visited[neighbor.atom]) {
        visited[neighbor.atom] = true; parent[neighbor.atom] = atom; queue.push(neighbor.atom);
      }
    }
    const paths = Array.from({ length: size }, (_, atom) => {
      const path = [atom];
      while (path[path.length - 1] !== root) path.push(parent[path[path.length - 1]]);
      return path;
    });
    for (const bond of molecule.bonds) {
      if (parent[bond.a] === bond.b || parent[bond.b] === bond.a) continue;
      const left = paths[bond.a], right = paths[bond.b], shared = new Set(left.slice(0, -1));
      if (right.slice(0, -1).some(atom => shared.has(atom))) continue;
      const sequence = left.slice().reverse().concat(right.slice(0, -1));
      let mask = 0n;
      for (let i = 0; i < sequence.length; i++) mask ^= 1n << BigInt(molecule.bond(sequence[i], sequence[(i + 1) % sequence.length])!.index);
      const key = mask.toString();
      if (!seen.has(key)) { seen.add(key); candidates.push({ sequence, mask, order: candidates.length }); }
    }
  }
  candidates.sort((a, b) => a.sequence.length - b.sequence.length || a.order - b.order);
  const basis = new Map<number,bigint>(), selected:number[][] = [];
  for (const candidate of candidates) {
    let reduced = candidate.mask;
    while (reduced !== 0n) {
      const pivot = reduced.toString(2).length - 1;
      if (!basis.has(pivot)) { basis.set(pivot, reduced); selected.push(normalizeRing(candidate.sequence)); break; }
      reduced ^= basis.get(pivot)!;
    }
  }
  selected.sort((a, b) => a.length - b.length || compareSequence(a, b));
  for (const ring of selected) for (let i = 0; i < ring.length; i++) {
    molecule.atoms[ring[i]].ring = true; molecule.bond(ring[i], ring[(i + 1) % ring.length])!.ring = true;
  }
  molecule.rings = selected;
  return selected;
}

export function kekulize(molecule:Molecule,needed:Set<number>):void {
  const visited = new Set<number>(), paired = new Set<number>(), doubleBonds = new Set<number>();
  for (const start of needed) {
    if (visited.has(start)) continue;
    const queue = [start]; visited.add(start);
    for (let front = 0; front < queue.length; front++) {
      for (const neighbor of molecule.atoms[queue[front]].neighbors) {
        if (neighbor.bond.type === 4 && needed.has(neighbor.atom) && !visited.has(neighbor.atom)) {
          visited.add(neighbor.atom); queue.push(neighbor.atom);
        }
      }
    }
    const system = queue.sort((a, b) => a - b), members = new Set(system);
    const search = ():boolean => {
      const first = system.find(atom => !paired.has(atom));
      if (first === undefined) return true;
      for (const neighbor of molecule.atoms[first].neighbors) {
        if (neighbor.bond.type !== 4 || !members.has(neighbor.atom) || paired.has(neighbor.atom)) continue;
        paired.add(first); paired.add(neighbor.atom); doubleBonds.add(neighbor.bond.index);
        if (search()) return true;
        paired.delete(first); paired.delete(neighbor.atom); doubleBonds.delete(neighbor.bond.index);
      }
      return false;
    };
    if (!search()) throw new MoleculeError('kekulization failed', molecule.atoms[system[0]].column);
  }
  for (const bond of molecule.bonds) bond.multiplicity = bond.type === 4 ? doubleBonds.has(bond.index) ? 2 : 1 : bond.type;
}

import {MoleculeError,Molecule} from './molecule.ts';
import {organicAtom} from './smiles_parser.ts';
import type {Atom,AtomRead,Element,Bond,Fingerprint,Embeddings,Similarity} from './types.ts';

const choice = (atom:Atom): {symbol:string;aromatic:boolean} => ({ symbol: atom.element.symbol, aromatic: atom.aromatic });

export function readPatternAtom(text:string,start:number,elements:Map<string,Element>):AtomRead|null {
  const character = text[start];
  if (character === '*' || character === 'A' || character === 'a') {
    return { atom: { matcher: { kind: character }, column: start + 1 }, next: start + 1 };
  }
  if (character === '[') {
    const end = text.indexOf(']', start + 1);
    if (end < 0) throw new MoleculeError('unclosed bracket', start + 1);
    const choices: {symbol:string;aromatic:boolean}[] = [];
    for (const word of text.slice(start + 1, end).split(',')) {
      const parsed = organicAtom(word, 0, elements);
      if (parsed === null || parsed.next !== word.length) throw new MoleculeError('bad bracket atom', start + 1);
      choices.push(choice(parsed.atom as Atom));
    }
    return { atom: { matcher: { kind: 'list', choices }, column: start + 1 }, next: end + 1 };
  }
  const parsed = organicAtom(text, start, elements);
  if (parsed === null) return null;
  return { atom: { matcher: { kind: 'list', choices: [choice(parsed.atom as Atom)] }, column: start + 1 }, next: parsed.next };
}

export function matchesAtom(pattern:Atom,atom:Atom):boolean {
  const matcher = pattern.matcher!;
  if (matcher.kind === '*') return true;
  if (matcher.kind === 'A') return !atom.aromatic;
  if (matcher.kind === 'a') return atom.aromatic;
  return matcher.choices!.some(item => item.symbol === atom.element.symbol && item.aromatic === atom.aromatic);
}

export const matchesBond = (pattern:Bond,bond:Bond):boolean => pattern.rawType === null ? bond.type === 1 || bond.type === 4 : pattern.rawType === 5 || pattern.rawType === bond.type;

export function moleculePattern(molecule:Molecule):Molecule {
  const pattern = new Molecule();
  for (const atom of molecule.atoms) pattern.addAtom({ matcher: { kind: 'list', choices: [choice(atom)] } });
  for (const bond of molecule.bonds) pattern.addBond(bond.a, bond.b, bond.type);
  return pattern.finalize();
}

export function embeddings(pattern:Molecule,molecule:Molecule):Embeddings {
  let count = 0, first: number[] | null = null;
  const unique = new Set<string>(), assignment:number[] = [], used = new Set<number>();
  if (pattern.atoms.length > molecule.atoms.length) return { count, unique: 0, first };
  const candidates = pattern.atoms.map(atom => molecule.atoms.filter(candidate =>
    candidate.neighbors.length >= atom.neighbors.length && matchesAtom(atom, candidate)).map(candidate => candidate.index));
  const visit = (index:number):void => {
    if (index === pattern.atoms.length) {
      count++;
      if (first === null) first = assignment.map(atom => atom + 1);
      unique.add(assignment.slice().sort((a, b) => a - b).join(',')); return;
    }
    for (const atom of candidates[index]) {
      if (used.has(atom)) continue;
      let valid = true;
      for (const neighbor of pattern.atoms[index].neighbors) if (neighbor.atom < index) {
        const bond = molecule.bond(atom, assignment[neighbor.atom]);
        if (!bond || !matchesBond(neighbor.bond, bond)) { valid = false; break; }
      }
      if (!valid) continue;
      assignment.push(atom); used.add(atom); visit(index + 1); used.delete(atom); assignment.pop();
    }
  };
  visit(0);
  return { count, unique: unique.size, first };
}

export function fingerprint(molecule:Molecule):Fingerprint {
  const codes = molecule.atoms.map(atom => 16 * atom.element.number + (atom.aromatic ? 8 : 0) + atom.neighbors.length);
  const bits = new Set<number>(), used = new Set<number>();
  let paths = 0;
  const visit = (atom:number,length:number,hash:number):void => {
    paths++; bits.add(hash % 1024);
    if (length === 5) return;
    for (const neighbor of molecule.atoms[atom].neighbors) if (!used.has(neighbor.atom)) {
      let next = (hash * 31 + neighbor.bond.type!) % 1000003;
      next = (next * 31 + codes[neighbor.atom]) % 1000003;
      used.add(neighbor.atom); visit(neighbor.atom, length + 1, next); used.delete(neighbor.atom);
    }
  };
  for (let atom = 0; atom < molecule.atoms.length; atom++) { used.add(atom); visit(atom, 0, codes[atom]); used.delete(atom); }
  return { bits, paths };
}

export function similarity(first:Fingerprint,second:Fingerprint):Similarity {
  let common = 0;
  for (const bit of first.bits) if (second.bits.has(bit)) common++;
  const union = first.bits.size + second.bits.size - common;
  return { p: common, q: union, common, union };
}

import {Molecule,MoleculeError} from './molecule.ts';
import type {AtomRead,Element} from './types.ts';
export const ORGANIC = new Set<string>(['B', 'C', 'N', 'O', 'P', 'S', 'F', 'Cl', 'Br', 'I']);
export const AROMATIC = new Set<string>(['b', 'c', 'n', 'o', 'p', 's']);
const digit = (character:string|undefined):boolean => character !== undefined && character >= '0' && character <= '9';
const uppercase = (character:string|undefined):boolean => character !== undefined && character >= 'A' && character <= 'Z';
const fail = (reason:string,column:number):never => { throw new MoleculeError(reason, column); };

export function organicAtom(text:string,start:number,elements:Map<string,Element>):AtomRead|null {
  const pair = text.slice(start, start + 2), symbol = pair === 'Cl' || pair === 'Br' ? pair : text[start];
  const aromatic = AROMATIC.has(symbol);
  if (!aromatic && !ORGANIC.has(symbol)) return null;
  return { atom: { element: elements.get(aromatic ? symbol.toUpperCase() : symbol)!, aromatic, mass: 0, charge: 0,
    hydrogens: 0, bracket: false, column: start + 1 }, next: start + symbol.length };
}

export function bracketAtom(text:string,start:number,elements:Map<string,Element>):AtomRead {
  const end = text.indexOf(']', start + 1);
  if (end < 0) fail('unclosed bracket', start + 1);
  const content = text.slice(start + 1, end);
  let i = 0;
  while (digit(content[i])) i++;
  if (i >= 4 || (i > 0 && content[0] === '0')) fail('bad bracket atom', start + 1);
  const mass = i === 0 ? 0 : Number(content.slice(0, i));
  let aromatic = false, symbol:string;
  if (AROMATIC.has(content[i])) { aromatic = true; symbol = content[i++].toUpperCase(); }
  else if (uppercase(content[i])) {
    const pair = content.slice(i, i + 2);
    if (pair.length === 2 && elements.has(pair)) { symbol = pair; i += 2; }
    else if (elements.has(content[i])) symbol = content[i++];
    else fail('unknown element', start + 1);
  } else fail('bad bracket atom', start + 1);
  if (content.slice(i, i + 2) === '@@') i += 2;
  else if (content[i] === '@') i++;
  let hydrogens = 0, charge = 0;
  if (content[i] === 'H') {
    i++; hydrogens = 1;
    if (digit(content[i])) hydrogens = Number(content[i++]);
  }
  if (content[i] === '+' || content[i] === '-') {
    charge = content[i++] === '+' ? 1 : -1;
    if (content[i] >= '1' && content[i] <= '9') charge *= Number(content[i++]);
  }
  if (i !== content.length) fail('bad bracket atom', start + 1);
  return { atom: { element: elements.get(symbol!)!, aromatic, mass, charge, hydrogens, bracket: true, column: start + 1 }, next: end + 1 };
}

export function parseSmiles(text:string,elements:Map<string,Element>,
  patternReader: ((text:string,start:number,elements:Map<string,Element>)=>AtomRead|null)|null = null):Molecule {
  const molecule = new Molecule();
  const stack: {atom:number;column:number}[] = [];
  const open = new Map<number,{atom:number;symbol:number|null;column:number}>();
  const types:Record<string,number> = patternReader ? { '-': 1, '=': 2, '#': 3, ':': 4, '~': 5 } : { '-': 1, '/': 1, '\\': 1, '=': 2, '#': 3, ':': 4 };
  let current:number|null = null, pending:{type:number;column:number}|null = null, i = 0;
  while (i < text.length) {
    const character = text[i], column = i + 1;
    if (Object.hasOwn(types, character)) {
      if (current === null || pending !== null) fail('misplaced bond', column);
      pending = { type: types[character], column }; i++;
    } else if (character === '(') {
      if (current === null || pending !== null || text[i - 1] === '(') fail('misplaced branch', column);
      stack.push({ atom: current, column }); i++;
    } else if (character === ')') {
      if (stack.length === 0) fail('unmatched parenthesis', column);
      if (pending !== null) fail('dangling bond', pending.column);
      if (text[i - 1] === '(') fail('empty branch', column);
      current = stack.pop()!.atom; i++;
    } else if (digit(character) || character === '%') {
      if (current === null) fail('misplaced ring closure', column);
      let number;
      if (character === '%') {
        if (!digit(text[i + 1]) || !digit(text[i + 2])) fail('bad ring number', column);
        number = Number(text.slice(i + 1, i + 3)); i += 3;
      } else { number = Number(character); i++; }
      const symbol = pending === null ? null : pending.type;
      pending = null;
      if (!open.has(number)) open.set(number, { atom: current, symbol, column });
      else {
        const opening = open.get(number)!;
        if (opening.atom === current) fail('self bond', column);
        if (opening.symbol !== null && symbol !== null && opening.symbol !== symbol) fail('ring bond mismatch', column);
        if (molecule.bond(opening.atom, current)) fail('duplicate bond', column);
        molecule.addBond(opening.atom, current, symbol === null ? opening.symbol : symbol); open.delete(number);
      }
    } else {
      const read = patternReader ? patternReader(text, i, elements) : character === '[' ? bracketAtom(text, i, elements) : organicAtom(text, i, elements);
      if (read === null) fail('unexpected character', column);
      const next = molecule.addAtom(read.atom);
      if (current !== null) molecule.addBond(current, next, pending === null ? null : pending.type);
      current = next; pending = null; i = read.next;
    }
  }
  if (pending !== null) fail('dangling bond', pending.column);
  if (stack.length) fail('unmatched parenthesis', stack[0].column);
  if (open.size) fail('unclosed ring', Math.min(...Array.from(open.values(), value => value.column)));
  return molecule.finalize();
}

